      `[gateway] gate integration=${plan.target.integration} tool=${plan.target.tool} ` +
        `permission=${plan.permission} outcome=${verdict.kind} ` +
        `rank=${rank > 0 ? rank : -1} searches=${gateway.memory.searches}`,
    );
